struct dpmatrix_s { int **xmx; };
struct plan7_s { int xsc[4][2]; };
struct p7trace_s { int tlen; char *statetype; int *nodeidx; int *pos; };
void PrintTransition(char, int, int, char, int, int, int, struct p7trace_s **, int *, int *, int *, int);

void DisplayPlan7PostAlign(int L, struct plan7_s *hmm, struct dpmatrix_s *forward,
                           struct dpmatrix_s *backward, struct p7trace_s **alignment, int A) {
  int sc = forward->xmx[L][2] + hmm->xsc[2][0];
  int *min = (int *)calloc(A, sizeof(int));
  int *max = (int *)calloc(A, sizeof(int));
  int *on = (int *)calloc(A, sizeof(int));
  for (int i = 0; i <= L; i++) {
    for (char state = 1; state <= 10; state++) {
      switch (state) {
        case 5:
          PrintTransition(5, i, 0, 6, i, 0, forward->xmx[i][4] + hmm->xsc[0][0] + backward->xmx[i][0] - sc,
                          alignment, min, max, on, A);
          if (i < L)
            PrintTransition(5, i, 0, 5, i + 1, 0, forward->xmx[i][4] + hmm->xsc[0][1] + backward->xmx[i+1][4] - sc,
                            alignment, min, max, on, A);
          break;
        default:
          Die("unknown state");
      }
    }
  }
  free(min); free(max); free(on);
}

void DisplayPlan7Posteriors(int L, struct plan7_s *hmm, struct dpmatrix_s *forward, struct dpmatrix_s *backward,
                            struct p7trace_s *viterbi, struct p7trace_s *optacc) {
  struct p7trace_s *alignment[2];
  alignment[0] = viterbi;
  alignment[1] = optacc;
  DisplayPlan7PostAlign(L, hmm, forward, backward, alignment, 2);
}

